1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.MembershipLevel;
8	import org.springframework.samples.petclinic.model.MembershipNumber;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Runs after {@link SaveOwner} on {@code POST /api/owners}, once the owner has been persisted and
13	 * assigned an id. Emits an audit line via the dedicated {@code AUDIT} logger carrying the new owner's
14	 * id, customerCode, registrationDate, membership level and membership number.
15	 */
16	public class AuditOwnerCreated {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner) {
21	        AUDIT.info(
22	                "Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
23	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
24	                MembershipLevel.of(owner), MembershipNumber.of(owner));
25	    }
26	}
