286	    /**
287	     * Return the Pet with the given name, or null if none found for this Owner.
288	     *
289	     * @param name to test
290	     * @return true if pet name is already in use
291	     */
292	    public Pet getPet(String name) {
293	        return getPet(name, false);
294	    }
295	
296	    /**
297	     * Return the Pet with the given name, or null if none found for this Owner.
298	     *
299	     * @param name to test
300	     * @return true if pet name is already in use
301	     */
302	    public Pet getPet(String name, boolean ignoreNew) {
303	        name = name.toLowerCase();
304	        for (Pet pet : getPetsInternal()) {
305	            if (!ignoreNew || !pet.isNew()) {
306	                String compName = pet.getName();
307	                compName = compName.toLowerCase();
308	                if (compName.equals(name)) {
309	                    return pet;
310	                }
311	            }
312	        }
313	        return null;
314	    }
315	
316	    public Pet getPet(Integer petId) {
317	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
318	    }
