320	    @Override
321	    public String toString() {
322	        return new ToStringCreator(this)
323	
324	            .append("id", this.getId())
325	            .append("new", this.isNew())
326	            .append("lastName", this.getLastName())
327	            .append("firstName", this.getFirstName())
328	            .append("address", this.address)
329	            .append("city", this.city)
330	            .append("telephone", this.telephone)
331	            .toString();
332	    }
333	}
