1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Single source of truth for an owner's {@code membershipNumber}: the derived value the owner response
5	 * carries and the create audit line records. The number is {@code <customerCode>-M<YY>}, where
6	 * {@code YY} is the two-digit fiscal year of the owner's (business-day-adjusted) registration date -
7	 * the fiscal year starts on 1 July, so the year segment comes from {@link FiscalYear}, not the calendar
8	 * year.
9	 *
10	 * <p>This is a model-level derivation of an {@link Owner} (like {@link MembershipLevel} and
11	 * {@link OwnerIdentity}): it is consumed both by the response mapper and by the create pipeline's
12	 * audit step, so it lives in the model layer rather than beside the pipeline functions.
13	 */
14	public final class MembershipNumber {
15	
16	    private MembershipNumber() {
17	    }
18	
19	    /** The {@code membershipNumber} of a persisted or in-flight owner, computed from its stored fields. */
20	    public static String of(Owner owner) {
21	        return owner.getCustomerCode() + "-M"
22	                + FiscalYear.twoDigitStartYear(owner.getRegistrationDate());
23	    }
24	}
